'use client';

import { useEffect, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Sheet, SheetContent, SheetTitle } from '@/registry/ndeko/ui/sheet';

import { ChildIssues } from './child-issues';
import { CommentComposer } from './comment-composer';
import { TASKS, type TaskDetail } from './data';
import { DescriptionBlock } from './description-block';
import {
  countLabel,
  keyOf,
  nextNumberOf,
  peopleOf,
  taskUrlOf,
  type FeedFilter,
} from './detail-model';
import { DrawerBar } from './drawer-bar';
import { PropertyRows } from './property-rows';
import { TaskBand } from './task-band';
import { commentOf, patchedTask, withComment } from './task-edits';
import { TaskFeed } from './task-feed';
import { IssueTypeGem, PeopleStack, StatusGlyph } from './task-glyphs';

const IGNORED_KEY_TARGETS =
  'input, textarea, select, [contenteditable="true"], [role="menu"]';

function isIgnoredKey(event: KeyboardEvent) {
  const isCommand = event.metaKey || event.ctrlKey;
  if (isCommand || event.altKey) {
    return true;
  }
  if (!(event.target instanceof HTMLElement)) {
    return false;
  }
  return Boolean(event.target.closest(IGNORED_KEY_TARGETS));
}

function stepOfKey(key: string) {
  const lowered = key.toLowerCase();
  if (lowered === 'j') {
    return 1;
  }
  if (lowered === 'k') {
    return -1;
  }
  return 0;
}

function positionOf(tasks: TaskDetail[], taskId: string) {
  const index = tasks.findIndex((task) => task.id === taskId);
  return Math.max(0, index);
}

function replacedTask(
  tasks: TaskDetail[],
  taskId: string,
  update: (task: TaskDetail) => TaskDetail
) {
  return tasks.map((task) => {
    if (task.id !== taskId) {
      return task;
    }
    return update(task);
  });
}

export default function TaskDetail01() {
  const [tasks, setTasks] = useState<TaskDetail[]>(TASKS);
  const [openId, setOpenId] = useState<string | null>(null);
  const [shownId, setShownId] = useState(TASKS[0].id);
  const [feedFilter, setFeedFilter] = useState<FeedFilter>('all');
  const [freshItemId, setFreshItemId] = useState<string | null>(null);
  const isOpen = openId !== null;
  const position = positionOf(tasks, shownId);
  const task = tasks[position];

  useEffect(() => {
    if (!isOpen) {
      return;
    }
    function walk(event: KeyboardEvent) {
      if (isIgnoredKey(event)) {
        return;
      }
      const step = stepOfKey(event.key);
      if (step === 0) {
        return;
      }
      const next = tasks[position + step];
      if (!next) {
        return;
      }
      event.preventDefault();
      setOpenId(next.id);
      setShownId(next.id);
    }
    document.addEventListener('keydown', walk);
    return () => document.removeEventListener('keydown', walk);
  }, [isOpen, position, tasks]);

  function open(taskId: string) {
    setOpenId(taskId);
    setShownId(taskId);
  }

  function handleOpenChange(nextOpen: boolean) {
    if (!nextOpen) {
      setOpenId(null);
    }
  }

  function step(delta: number) {
    const next = tasks[position + delta];
    if (next) {
      open(next.id);
    }
  }

  function patch(changes: Partial<TaskDetail>) {
    setTasks((current) =>
      replacedTask(current, task.id, (item) => patchedTask(item, changes))
    );
  }

  function postComment(body: string) {
    const comment = commentOf(body);
    setTasks((current) =>
      replacedTask(current, task.id, (item) => withComment(item, comment))
    );
    setFreshItemId(comment.id);
    if (feedFilter === 'history') {
      setFeedFilter('all');
    }
  }

  return (
    <div className='bg-background text-foreground min-h-svh px-4 py-6 sm:px-8 sm:py-10'>
      <div className='mx-auto max-w-2xl'>
        <h1 className='text-sm font-semibold'>Cycle 14</h1>
        <p className='text-muted-foreground text-xs'>
          Nov 2 to Nov 15 · {countLabel(tasks.length, 'task', 'tasks')}
        </p>
        <ul className='bg-card hairline-ring ring-border hairline-divide-y divide-border mt-4 overflow-clip rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
          {tasks.map((item) => {
            const isCurrent = isOpen && item.id === shownId;
            return (
              <li key={item.id}>
                <button
                  type='button'
                  aria-haspopup='dialog'
                  onClick={() => open(item.id)}
                  className={cn(
                    'hover:bg-foreground/[0.03] focus-visible:bg-foreground/[0.05] flex h-11 w-full cursor-pointer items-center gap-3 px-3 text-left outline-none',
                    isCurrent && 'bg-primary/[0.06] hover:bg-primary/[0.08]'
                  )}
                >
                  <StatusGlyph status={item.status} />
                  <span className='text-muted-foreground hidden w-14 shrink-0 text-xs tabular-nums sm:inline'>
                    {keyOf(item.number)}
                  </span>
                  <IssueTypeGem type={item.type} />
                  <span className='min-w-0 flex-1 truncate text-[13px]'>
                    {item.title}
                  </span>
                  <PeopleStack
                    people={peopleOf(item.assigneeIds)}
                    ringClassName='ring-card'
                  />
                </button>
              </li>
            );
          })}
        </ul>
      </div>
      <Sheet open={isOpen} onOpenChange={handleOpenChange}>
        <SheetContent
          showCloseButton={false}
          className='w-[calc(100%-1rem)] max-w-[42rem] gap-0 overflow-hidden p-0'
        >
          <DrawerBar
            position={position + 1}
            total={tasks.length}
            link={taskUrlOf(task.number)}
            onPrevious={() => step(-1)}
            onNext={() => step(1)}
          />
          <div
            key={task.id}
            className='@container min-h-0 flex-1 overflow-y-auto px-5 pb-6'
          >
            <TaskBand task={task} />
            <SheetTitle className='mt-5 text-xl leading-snug font-semibold text-balance'>
              {task.title}
            </SheetTitle>
            {task.parent && (
              <p className='text-muted-foreground mt-1 text-xs'>
                Part of {keyOf(task.parent.number)} {task.parent.title}
              </p>
            )}
            <div className='mt-5'>
              <PropertyRows task={task} onPatch={patch} columns={2} />
            </div>
            <div className='mt-8'>
              <DescriptionBlock
                paragraphs={task.description}
                onSave={(description) => patch({ description })}
              />
            </div>
            <div className='mt-8'>
              <ChildIssues
                items={task.children}
                nextNumber={nextNumberOf(tasks)}
                onChange={(children) => patch({ children })}
              />
            </div>
            <div className='mt-8'>
              <TaskFeed
                items={task.feed}
                filter={feedFilter}
                onFilterChange={setFeedFilter}
                freshItemId={freshItemId}
              />
            </div>
          </div>
          <div className='before:from-card relative shrink-0 px-5 pt-3 pb-4 before:pointer-events-none before:absolute before:inset-x-0 before:-top-4 before:h-4 before:bg-linear-to-t before:to-transparent'>
            <CommentComposer onSubmit={postComment} />
          </div>
        </SheetContent>
      </Sheet>
    </div>
  );
}

'use client';

import {
  CheckIcon,
  ChevronDownIcon,
  ChevronUpIcon,
  LinkIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Kbd } from '@/registry/ndeko/ui/kbd';
import { SheetClose } from '@/registry/ndeko/ui/sheet';
import {
  TOOLTIP_GLIDE_CLOSE_DELAY,
  Tooltip,
  TooltipContent,
  TooltipTrigger,
  useTooltipHandle,
} from '@/registry/ndeko/ui/tooltip';

import { Swap } from './motion-parts';
import { useCopied } from './use-copied';

type TaskStepHint = { label: string; shortcut: string };

const PREVIOUS_TASK_HINT: TaskStepHint = {
  label: 'Previous task',
  shortcut: 'K',
};

const NEXT_TASK_HINT: TaskStepHint = { label: 'Next task', shortcut: 'J' };

function TaskStepHintLabel({ hint }: { hint: TaskStepHint | undefined }) {
  if (!hint) {
    return null;
  }
  return (
    <>
      {hint.label} <Kbd>{hint.shortcut}</Kbd>
    </>
  );
}

type DrawerBarProps = {
  position: number;
  total: number;
  link: string;
  onPrevious: () => void;
  onNext: () => void;
};

function copyLabelOf(isCopied: boolean) {
  if (isCopied) {
    return 'Link copied';
  }
  return 'Copy link';
}

export function DrawerBar({
  position,
  total,
  link,
  onPrevious,
  onNext,
}: DrawerBarProps) {
  const { isCopied, copy } = useCopied();
  const isFirst = position <= 1;
  const isLast = position >= total;
  const stepHint = useTooltipHandle<TaskStepHint>();

  return (
    <div className='flex h-12 shrink-0 items-center gap-1 px-3'>
      <TooltipTrigger
        handle={stepHint}
        payload={PREVIOUS_TASK_HINT}
        closeDelay={TOOLTIP_GLIDE_CLOSE_DELAY}
        render={
          <Button
            variant='ghost'
            size='icon-sm'
            aria-label='Previous task'
            disabled={isFirst}
            onClick={onPrevious}
          />
        }
      >
        <ChevronUpIcon />
      </TooltipTrigger>
      <TooltipTrigger
        handle={stepHint}
        payload={NEXT_TASK_HINT}
        closeDelay={TOOLTIP_GLIDE_CLOSE_DELAY}
        render={
          <Button
            variant='ghost'
            size='icon-sm'
            aria-label='Next task'
            disabled={isLast}
            onClick={onNext}
          />
        }
      >
        <ChevronDownIcon />
      </TooltipTrigger>
      <Tooltip handle={stepHint}>
        {({ payload }) => (
          <TooltipContent glide>
            <TaskStepHintLabel hint={payload} />
          </TooltipContent>
        )}
      </Tooltip>
      <span className='text-muted-foreground ms-1 text-xs tabular-nums'>
        {position} of {total}
      </span>
      <div className='ms-auto flex items-center gap-1'>
        <Button
          variant='ghost'
          size='icon-sm'
          aria-label={copyLabelOf(isCopied)}
          onClick={() => copy(link)}
        >
          <Swap swapKey={String(isCopied)}>
            {isCopied && <CheckIcon className='text-success-foreground' />}
            {!isCopied && <LinkIcon />}
          </Swap>
        </Button>
        <SheetClose
          render={<Button variant='ghost' size='icon-sm' aria-label='Close' />}
        >
          <XIcon />
        </SheetClose>
      </div>
    </div>
  );
}

import { TEAM_NAME, type TaskDetail } from './data';
import { issueTypeOf, keyOf, shortDateOf, statusOf } from './detail-model';
import { Swap } from './motion-parts';
import { IssueTypeGem, StatusGlyph } from './task-glyphs';

export function TaskBand({ task }: { task: TaskDetail }) {
  const type = issueTypeOf(task.type);
  const status = statusOf(task.status);

  return (
    <div className='bg-foreground/[0.03] text-muted-foreground flex flex-wrap items-center gap-x-4 gap-y-1.5 rounded-lg px-3 py-2 text-xs'>
      <span className='text-foreground flex items-center gap-1.5 font-medium'>
        <IssueTypeGem type={task.type} />
        {type.name}
      </span>
      <span>{TEAM_NAME}</span>
      <span className='tabular-nums'>{keyOf(task.number)}</span>
      <span>Created {shortDateOf(task.createdAt)}</span>
      <span className='text-foreground ms-auto flex items-center gap-1.5'>
        <Swap swapKey={task.status}>
          <StatusGlyph status={task.status} />
        </Swap>
        {status.name}
      </span>
    </div>
  );
}

'use client';

import {
  CalendarIcon,
  CircleDashedIcon,
  ClockIcon,
  HashIcon,
  PlusIcon,
  UsersIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Chip } from '@/registry/ndeko/ui/chip';
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import { LABELS, PEOPLE, PRIORITIES, STATUSES, type TaskDetail } from './data';
import {
  datePresetsOf,
  durationLabel,
  ESTIMATE_PRESETS,
  isOverdue,
  isPriorityId,
  isStatusId,
  labelsOf,
  longDateOf,
  peopleOf,
  priorityOf,
  statusOf,
  toggledIds,
} from './detail-model';
import { Swap } from './motion-parts';
import { PersonAvatar, PriorityGlyph, StatusGlyph } from './task-glyphs';

type Patch = (patch: Partial<TaskDetail>) => void;

const VALUE_TRIGGER =
  'inline-flex h-7 min-w-0 max-w-full -mx-1.5 cursor-pointer items-center gap-1.5 rounded-md px-1.5 text-[13px] outline-none transition-colors duration-150 hover:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25 data-popup-open:bg-foreground/5';

const ADD_SLOT =
  'inline-flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-full hairline-border border-dashed border-foreground/20 text-muted-foreground outline-none transition-colors duration-150 hover:border-foreground/35 hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/25 data-popup-open:border-foreground/35';

function EmptyValue({ text }: { text: string }) {
  return (
    <span className='text-muted-foreground inline-flex items-center gap-1'>
      <PlusIcon className='size-3.5' />
      {text}
    </span>
  );
}

type PropertyRowProps = {
  icon: React.ReactNode;
  label: string;
  children: React.ReactNode;
};

function PropertyRow({ icon, label, children }: PropertyRowProps) {
  return (
    <div className='flex min-h-9 items-center gap-2'>
      <div className='text-muted-foreground flex w-[6.75rem] shrink-0 items-center gap-2 text-[13px] [&_svg]:size-4'>
        {icon}
        {label}
      </div>
      <div className='flex min-w-0 flex-1 flex-wrap items-center gap-1'>
        {children}
      </div>
    </div>
  );
}

function StatusValue({ task, onPatch }: { task: TaskDetail; onPatch: Patch }) {
  const meta = statusOf(task.status);

  function pick(value: unknown) {
    if (isStatusId(value)) {
      onPatch({ status: value });
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        aria-label={`Status: ${meta.name}. Change status`}
        className={VALUE_TRIGGER}
      >
        <Swap swapKey={task.status}>
          <StatusGlyph status={task.status} />
        </Swap>
        <span className='truncate'>{meta.name}</span>
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-48'>
        <DropdownMenuRadioGroup value={task.status} onValueChange={pick}>
          {STATUSES.map((status) => (
            <DropdownMenuRadioItem
              key={status.id}
              value={status.id}
              closeOnClick
            >
              <StatusGlyph status={status.id} />
              {status.name}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function PriorityValue({
  task,
  onPatch,
}: {
  task: TaskDetail;
  onPatch: Patch;
}) {
  const meta = priorityOf(task.priority);
  const isUnset = task.priority === 'none';

  function pick(value: unknown) {
    if (isPriorityId(value)) {
      onPatch({ priority: value });
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        aria-label={`Priority: ${meta.name}. Change priority`}
        className={VALUE_TRIGGER}
      >
        {isUnset && <EmptyValue text='Set priority' />}
        {!isUnset && (
          <>
            <Swap swapKey={task.priority}>
              <PriorityGlyph priority={task.priority} />
            </Swap>
            <span className='truncate'>{meta.name}</span>
          </>
        )}
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-44'>
        <DropdownMenuRadioGroup value={task.priority} onValueChange={pick}>
          {PRIORITIES.map((priority) => (
            <DropdownMenuRadioItem
              key={priority.id}
              value={priority.id}
              closeOnClick
            >
              <PriorityGlyph priority={priority.id} />
              {priority.name}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function firstNameOf(name: string) {
  return name.split(' ')[0];
}

function PeopleValue({ task, onPatch }: { task: TaskDetail; onPatch: Patch }) {
  const assignees = peopleOf(task.assigneeIds);
  const hasAssignees = assignees.length > 0;

  function toggle(personId: string, isIncluded: boolean) {
    onPatch({
      assigneeIds: toggledIds(task.assigneeIds, personId, isIncluded),
    });
  }

  const menu = (
    <DropdownMenuContent className='w-52'>
      {PEOPLE.map((person) => (
        <DropdownMenuCheckboxItem
          key={person.id}
          checked={task.assigneeIds.includes(person.id)}
          onCheckedChange={(checked) => toggle(person.id, checked)}
        >
          <PersonAvatar person={person} />
          {person.name}
        </DropdownMenuCheckboxItem>
      ))}
    </DropdownMenuContent>
  );

  if (!hasAssignees) {
    return (
      <DropdownMenu>
        <DropdownMenuTrigger className={VALUE_TRIGGER}>
          <EmptyValue text='Add people' />
        </DropdownMenuTrigger>
        {menu}
      </DropdownMenu>
    );
  }

  return (
    <>
      {assignees.map((person) => (
        <span
          key={person.id}
          className='bg-card hairline-ring ring-border inline-flex h-6 max-w-40 items-center gap-1.5 rounded-full ps-0.5 pe-2 text-xs'
        >
          <PersonAvatar person={person} />
          <span className='truncate'>{firstNameOf(person.name)}</span>
        </span>
      ))}
      <DropdownMenu>
        <DropdownMenuTrigger aria-label='Change people' className={ADD_SLOT}>
          <PlusIcon className='size-3.5' />
        </DropdownMenuTrigger>
        {menu}
      </DropdownMenu>
    </>
  );
}

function LabelsValue({ task, onPatch }: { task: TaskDetail; onPatch: Patch }) {
  const labels = labelsOf(task.labelIds);
  const hasLabels = labels.length > 0;

  function toggle(labelId: string, isIncluded: boolean) {
    onPatch({ labelIds: toggledIds(task.labelIds, labelId, isIncluded) });
  }

  const menu = (
    <DropdownMenuContent className='w-48'>
      {LABELS.map((label) => {
        const dotStyle = {
          backgroundColor: label.color,
        } as React.CSSProperties;
        return (
          <DropdownMenuCheckboxItem
            key={label.id}
            checked={task.labelIds.includes(label.id)}
            onCheckedChange={(checked) => toggle(label.id, checked)}
          >
            <span
              aria-hidden='true'
              style={dotStyle}
              className='mx-1 size-2 shrink-0 rounded-full'
            />
            {label.name}
          </DropdownMenuCheckboxItem>
        );
      })}
    </DropdownMenuContent>
  );

  if (!hasLabels) {
    return (
      <DropdownMenu>
        <DropdownMenuTrigger className={VALUE_TRIGGER}>
          <EmptyValue text='Add label' />
        </DropdownMenuTrigger>
        {menu}
      </DropdownMenu>
    );
  }

  return (
    <>
      {labels.map((label) => (
        <Chip key={label.id} color={label.color} className='h-6 px-2'>
          {label.name}
        </Chip>
      ))}
      <DropdownMenu>
        <DropdownMenuTrigger aria-label='Change labels' className={ADD_SLOT}>
          <PlusIcon className='size-3.5' />
        </DropdownMenuTrigger>
        {menu}
      </DropdownMenu>
    </>
  );
}

function dueToneOf(task: TaskDetail) {
  if (isOverdue(task)) {
    return 'text-destructive-ink';
  }
  return '';
}

function DueValue({ task, onPatch }: { task: TaskDetail; onPatch: Patch }) {
  const presets = datePresetsOf();

  function pick(value: unknown) {
    if (typeof value === 'string') {
      onPatch({ due: value });
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger className={VALUE_TRIGGER}>
        {!task.due && <EmptyValue text='Add date' />}
        {task.due && (
          <Swap swapKey={task.due} className={dueToneOf(task)}>
            {longDateOf(task.due)}
            {isOverdue(task) && <span className='sr-only'>, overdue</span>}
          </Swap>
        )}
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-60'>
        <DropdownMenuRadioGroup value={task.due ?? ''} onValueChange={pick}>
          {presets.map((preset) => (
            <DropdownMenuRadioItem
              key={preset.label}
              value={preset.date}
              closeOnClick
            >
              <CalendarIcon />
              <span className='flex-1'>{preset.label}</span>
              <span className='text-muted-foreground text-xs tabular-nums'>
                {longDateOf(preset.date)}
              </span>
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
        {task.due && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={() => onPatch({ due: undefined })}>
              <XIcon />
              Clear date
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function EstimateValue({
  task,
  onPatch,
}: {
  task: TaskDetail;
  onPatch: Patch;
}) {
  const estimate = task.estimateMinutes;
  const hasEstimate = estimate !== undefined;

  function pick(value: unknown) {
    const minutes = Number(value);
    if (Number.isFinite(minutes)) {
      onPatch({ estimateMinutes: minutes });
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger className={VALUE_TRIGGER}>
        {!hasEstimate && <EmptyValue text='Estimate' />}
        {hasEstimate && (
          <Swap swapKey={String(estimate)} className='tabular-nums'>
            {durationLabel(estimate)}
          </Swap>
        )}
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-40'>
        <DropdownMenuRadioGroup
          value={String(estimate ?? '')}
          onValueChange={pick}
        >
          {ESTIMATE_PRESETS.map((minutes) => (
            <DropdownMenuRadioItem
              key={minutes}
              value={String(minutes)}
              closeOnClick
            >
              <ClockIcon />
              <span className='tabular-nums'>{durationLabel(minutes)}</span>
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
        {hasEstimate && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              onClick={() => onPatch({ estimateMinutes: undefined })}
            >
              <XIcon />
              Clear estimate
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

type PropertyRowsProps = {
  task: TaskDetail;
  onPatch: Patch;
  columns: 1 | 2;
};

export function PropertyRows({ task, onPatch, columns }: PropertyRowsProps) {
  const isTwoColumn = columns === 2;

  return (
    <div className={cn('grid gap-x-8', isTwoColumn && '@xl:grid-cols-2')}>
      <PropertyRow icon={<CircleDashedIcon />} label='Status'>
        <StatusValue task={task} onPatch={onPatch} />
      </PropertyRow>
      <PropertyRow
        icon={
          <PriorityGlyph priority='high' className='text-muted-foreground' />
        }
        label='Priority'
      >
        <PriorityValue task={task} onPatch={onPatch} />
      </PropertyRow>
      <PropertyRow icon={<UsersIcon />} label='People'>
        <PeopleValue task={task} onPatch={onPatch} />
      </PropertyRow>
      <PropertyRow icon={<HashIcon />} label='Labels'>
        <LabelsValue task={task} onPatch={onPatch} />
      </PropertyRow>
      <PropertyRow icon={<CalendarIcon />} label='Due date'>
        <DueValue task={task} onPatch={onPatch} />
      </PropertyRow>
      <PropertyRow icon={<ClockIcon />} label='Estimate'>
        <EstimateValue task={task} onPatch={onPatch} />
      </PropertyRow>
    </div>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';

import { PencilIcon, PlusIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Textarea } from '@/registry/ndeko/ui/textarea';

function paragraphsOf(text: string) {
  const blocks = text.split(/\n\s*\n/);
  const trimmed = blocks.map((block) => block.trim());
  return trimmed.filter(Boolean);
}

type DescriptionBlockProps = {
  paragraphs: string[];
  onSave: (paragraphs: string[]) => void;
};

export function DescriptionBlock({
  paragraphs,
  onSave,
}: DescriptionBlockProps) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [draft, setDraft] = useState('');
  const isEmpty = paragraphs.length === 0;
  const showsText = !isEditing && !isEmpty;
  const showsAdd = !isEditing && isEmpty;

  useEffect(() => {
    if (isEditing) {
      textareaRef.current?.focus();
    }
  }, [isEditing]);

  function startEditing() {
    setDraft(paragraphs.join('\n\n'));
    setIsEditing(true);
  }

  function cancel() {
    setIsEditing(false);
  }

  function save() {
    onSave(paragraphsOf(draft));
    setIsEditing(false);
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      cancel();
      return;
    }
    const isCommand = event.metaKey || event.ctrlKey;
    if (event.key === 'Enter' && isCommand) {
      event.preventDefault();
      save();
    }
  }

  return (
    <section aria-label='Description'>
      <div className='flex h-7 items-center justify-between gap-2'>
        <h3 className='text-[13px] font-medium'>Description</h3>
        {showsText && (
          <Button
            variant='ghost'
            size='sm'
            onClick={startEditing}
            className='text-muted-foreground'
          >
            <PencilIcon />
            Edit
          </Button>
        )}
      </div>
      <AnimatedSize className='mt-2'>
        {showsText && (
          <div
            onDoubleClick={startEditing}
            className='flex flex-col gap-3 text-sm leading-relaxed text-pretty'
          >
            {paragraphs.map((paragraph) => (
              <p key={paragraph}>{paragraph}</p>
            ))}
          </div>
        )}
        {showsAdd && (
          <button
            type='button'
            onClick={startEditing}
            className='text-muted-foreground hover:text-foreground focus-visible:ring-ring/25 inline-flex h-7 cursor-pointer items-center gap-1 rounded-md text-[13px] outline-none focus-visible:ring-[3px]'
          >
            <PlusIcon className='size-3.5' />
            Add a description
          </button>
        )}
        {isEditing && (
          <div className='flex flex-col gap-2'>
            <Textarea
              ref={textareaRef}
              value={draft}
              onChange={(event) => setDraft(event.target.value)}
              onKeyDown={handleKeyDown}
              aria-label='Description'
              placeholder='What needs to happen, and why'
              className='min-h-28 text-base leading-relaxed md:text-sm'
            />
            <div className='flex items-center justify-end gap-2'>
              <Button variant='ghost' size='sm' onClick={cancel}>
                Cancel
              </Button>
              <Button size='sm' onClick={save}>
                Save
              </Button>
            </div>
          </div>
        )}
      </AnimatedSize>
    </section>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';

import type { ChildIssue, StatusId } from './data';
import { keyOf, personOf, statusOf } from './detail-model';
import { heightPresenceOf, Swap } from './motion-parts';
import { PersonAvatar, StatusGlyph } from './task-glyphs';

const RING_RADIUS = 6;
const RING_CIRCUMFERENCE = 2 * Math.PI * RING_RADIUS;

const ADD_ROW =
  'flex h-9 w-full items-center gap-2.5 rounded-lg px-2.5 text-[13px] text-muted-foreground hairline-border border-dashed border-foreground/20 outline-none transition-colors duration-150';

function shareOf(done: number, total: number) {
  if (total === 0) {
    return 0;
  }
  return done / total;
}

function ProgressRing({ done, total }: { done: number; total: number }) {
  const share = shareOf(done, total);
  const offset = RING_CIRCUMFERENCE * (1 - share);

  return (
    <svg viewBox='0 0 16 16' aria-hidden='true' className='size-4 -rotate-90'>
      <circle
        cx='8'
        cy='8'
        r={RING_RADIUS}
        fill='none'
        stroke='currentColor'
        strokeWidth='2'
        className='text-foreground/10'
      />
      <circle
        cx='8'
        cy='8'
        r={RING_RADIUS}
        fill='none'
        stroke='var(--success)'
        strokeWidth='2'
        strokeDasharray={RING_CIRCUMFERENCE}
        strokeDashoffset={offset}
        className='transition-[stroke-dashoffset] duration-300 ease-(--ease-out-strong)'
      />
    </svg>
  );
}

function nextStatusOf(status: StatusId): StatusId {
  if (status === 'done') {
    return 'todo';
  }
  return 'done';
}

function toggleLabelOf(child: ChildIssue) {
  const key = keyOf(child.number);
  if (child.status === 'done') {
    return `Reopen ${key}`;
  }
  return `Mark ${key} as done`;
}

function assigneeOf(child: ChildIssue) {
  if (!child.assigneeId) {
    return undefined;
  }
  return personOf(child.assigneeId);
}

function ChildRow({
  child,
  onToggle,
}: {
  child: ChildIssue;
  onToggle: (childId: string) => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  const presence = heightPresenceOf(shouldReduceMotion);
  const isDone = child.status === 'done';
  const assignee = assigneeOf(child);

  return (
    <motion.li {...presence} className='overflow-hidden'>
      <div className='flex h-9 items-center gap-2.5 px-1.5'>
        <button
          type='button'
          aria-label={toggleLabelOf(child)}
          onClick={() => onToggle(child.id)}
          className='hover:bg-foreground/5 focus-visible:ring-ring/25 inline-flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-md outline-none focus-visible:ring-[3px]'
        >
          <Swap swapKey={child.status}>
            <StatusGlyph status={child.status} />
          </Swap>
        </button>
        <span className='text-muted-foreground w-14 shrink-0 text-xs tabular-nums'>
          {keyOf(child.number)}
        </span>
        <span
          className={cn(
            'min-w-0 flex-1 truncate text-[13px]',
            isDone && 'text-muted-foreground line-through'
          )}
        >
          {child.title}
        </span>
        <span className='sr-only'>{statusOf(child.status).name}</span>
        {assignee && <PersonAvatar person={assignee} className='me-1' />}
      </div>
    </motion.li>
  );
}

type ChildIssuesProps = {
  items: ChildIssue[];
  nextNumber: number;
  onChange: (items: ChildIssue[]) => void;
};

export function ChildIssues({ items, nextNumber, onChange }: ChildIssuesProps) {
  const [isAdding, setIsAdding] = useState(false);
  const [title, setTitle] = useState('');
  const doneCount = items.filter((child) => child.status === 'done').length;
  const hasItems = items.length > 0;

  function toggle(childId: string) {
    const next = items.map((child) => {
      if (child.id !== childId) {
        return child;
      }
      return { ...child, status: nextStatusOf(child.status) };
    });
    onChange(next);
  }

  function add() {
    const trimmed = title.trim();
    if (!trimmed) {
      return;
    }
    const child: ChildIssue = {
      id: `child-${nextNumber}`,
      number: nextNumber,
      title: trimmed,
      status: 'todo',
    };
    onChange([...items, child]);
    setTitle('');
  }

  function stopAdding() {
    setIsAdding(false);
    setTitle('');
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Enter') {
      event.preventDefault();
      add();
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      stopAdding();
    }
  }

  function handleBlur() {
    const isEmpty = title.trim().length === 0;
    if (isEmpty) {
      stopAdding();
    }
  }

  return (
    <section aria-label='Child issues'>
      <div className='flex h-7 items-center gap-2'>
        <h3 className='text-[13px] font-medium'>Child issues</h3>
        {hasItems && (
          <span className='text-muted-foreground flex items-center gap-1.5 text-xs tabular-nums'>
            <ProgressRing done={doneCount} total={items.length} />
            <span aria-hidden='true' className='flex'>
              <MotionNumber value={doneCount} />/
              <MotionNumber value={items.length} />
            </span>
            <span className='sr-only'>
              {doneCount} of {items.length} done
            </span>
          </span>
        )}
      </div>
      <div className='mt-2 flex flex-col gap-2'>
        {hasItems && (
          <ul className='bg-card hairline-ring ring-border hairline-divide-y divide-border overflow-clip rounded-lg'>
            <AnimatePresence initial={false}>
              {items.map((child) => (
                <ChildRow key={child.id} child={child} onToggle={toggle} />
              ))}
            </AnimatePresence>
          </ul>
        )}
        {!isAdding && (
          <button
            type='button'
            onClick={() => setIsAdding(true)}
            className={cn(
              ADD_ROW,
              'hover:border-foreground/35 hover:text-foreground focus-visible:ring-ring/25 cursor-pointer focus-visible:ring-[3px]'
            )}
          >
            <PlusIcon className='size-4' />
            Add child issue
          </button>
        )}
        {isAdding && (
          <div className={cn(ADD_ROW, 'border-foreground/35 text-foreground')}>
            <StatusGlyph status='todo' />
            <input
              autoFocus
              value={title}
              onChange={(event) => setTitle(event.target.value)}
              onKeyDown={handleKeyDown}
              onBlur={handleBlur}
              aria-label='Child issue title'
              placeholder='Child issue title, then Enter'
              className='placeholder:text-muted-foreground/75 h-7 min-w-0 flex-1 bg-transparent text-base outline-none md:text-[13px]'
            />
          </div>
        )}
      </div>
    </section>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useRef } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import {
  CircleDashedIcon,
  ClockIcon,
  HashIcon,
  PlusIcon,
  UserIcon,
} from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import type { ChangeKind, FeedChange, FeedComment, FeedItem } from './data';
import {
  dayGroupsOf,
  feedCountsOf,
  isFeedFilter,
  personOf,
  timeOf,
  type FeedFilter,
} from './detail-model';
import { heightPresenceOf } from './motion-parts';
import { PersonAvatar, PriorityGlyph } from './task-glyphs';

const FILTERS: { id: FeedFilter; label: string }[] = [
  { id: 'all', label: 'All' },
  { id: 'comments', label: 'Comments' },
  { id: 'history', label: 'History' },
];

const EMPTY_LINE: Record<FeedFilter, string> = {
  all: 'Nothing has happened on this task yet',
  comments: 'No comments yet, write the first one below',
  history: 'No changes recorded yet',
};

const CHANGE_GLYPH: Record<ChangeKind, React.ReactNode> = {
  created: <PlusIcon />,
  status: <CircleDashedIcon />,
  assignee: <UserIcon />,
  estimate: <ClockIcon />,
  label: <HashIcon />,
  priority: <PriorityGlyph priority='high' className='text-muted-foreground' />,
};

const THREAD =
  'relative before:absolute before:inset-y-4 before:start-3 before:hairline-l before:border-dashed before:border-foreground/15';

function scrollBehaviorOf(shouldReduceMotion: boolean | null): ScrollBehavior {
  if (shouldReduceMotion) {
    return 'auto';
  }
  return 'smooth';
}

function CommentEntry({ item }: { item: FeedComment }) {
  const author = personOf(item.authorId);
  return (
    <div className='flex gap-3'>
      <PersonAvatar person={author} className='relative size-6 text-[10px]' />
      <div className='min-w-0 flex-1 pt-0.5'>
        <p className='flex items-baseline gap-2 text-[13px]'>
          <span className='font-medium'>{author.name}</span>
          <time
            dateTime={item.at}
            className='text-muted-foreground text-xs tabular-nums'
          >
            {timeOf(item.at)}
          </time>
        </p>
        <p className='mt-1 text-[13px] leading-relaxed whitespace-pre-line'>
          {item.body}
        </p>
      </div>
    </div>
