function FeedEntry({ item, isFresh }: { item: FeedItem; isFresh: boolean }) {
  const shouldReduceMotion = useReducedMotion();
  const presence = heightPresenceOf(shouldReduceMotion);
  const entryRef = useRef<HTMLLIElement>(null);

  function revealIfFresh() {
    if (!isFresh) {
      return;
    }
    entryRef.current?.scrollIntoView({
      block: 'nearest',
      behavior: scrollBehaviorOf(shouldReduceMotion),
    });
  }

  return (
    <motion.li
      ref={entryRef}
      {...presence}
      onAnimationComplete={revealIfFresh}
      className='overflow-hidden'
    >
      <div className='py-1.5'>
        {item.kind === 'comment' && <CommentEntry item={item} />}
        {item.kind === 'change' && <ChangeEntry item={item} />}
      </div>
    </motion.li>
  );
}

function DayGroupBlock({
  label,
  items,
  freshItemId,
}: {
  label: string;
  items: FeedItem[];
  freshItemId: string | null;
}) {
  const shouldReduceMotion = useReducedMotion();
  const presence = heightPresenceOf(shouldReduceMotion);

  return (
    <motion.div {...presence} className='overflow-hidden'>
      <p className='text-muted-foreground pt-3 pb-1 text-xs font-medium'>
        {label}
      </p>
      <ul className={THREAD}>
        <AnimatePresence initial={false}>
          {items.map((item) => (
            <FeedEntry
              key={item.id}
              item={item}
              isFresh={item.id === freshItemId}
            />
          ))}
        </AnimatePresence>
      </ul>
    </motion.div>
  );
}

type TaskFeedProps = {
  items: FeedItem[];
  filter: FeedFilter;
  onFilterChange: (filter: FeedFilter) => void;
  freshItemId: string | null;
  children?: React.ReactNode;
};

export function TaskFeed({
  items,
  filter,
  onFilterChange,
  freshItemId,
  children,
}: TaskFeedProps) {
  const counts = feedCountsOf(items);
  const groups = dayGroupsOf(items, filter);
  const isEmpty = groups.length === 0;

  function change(value: unknown) {
    if (isFeedFilter(value)) {
      onFilterChange(value);
    }
  }

  return (
    <section aria-label='Activity'>
      <div className='flex flex-wrap items-center justify-between gap-2'>
        <h3 className='text-[13px] font-medium'>Activity</h3>
        <Tabs value={filter} onValueChange={change}>
          <TabsList variant='segmented' aria-label='What the activity shows'>
            {FILTERS.map((option) => (
              <TabsTab key={option.id} value={option.id}>
                {option.label}
                <MotionNumber
                  value={counts[option.id]}
                  className='text-muted-foreground text-xs'
                />
              </TabsTab>
            ))}
          </TabsList>
        </Tabs>
      </div>
      <AnimatedSize className='mt-1'>
        <div key={filter}>
          {isEmpty && (
            <p className='text-muted-foreground py-4 text-[13px]'>
              {EMPTY_LINE[filter]}
            </p>
          )}
          <AnimatePresence initial={false}>
            {groups.map((group) => (
              <DayGroupBlock
                key={group.day}
                label={group.label}
                items={group.items}
                freshItemId={freshItemId}
              />
            ))}
          </AnimatePresence>
        </div>
      </AnimatedSize>
      {children}
    </section>
  );
}

'use client';

import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import { currentUser } from './detail-model';
import { PersonAvatar } from './task-glyphs';

type CommentComposerProps = {
  onSubmit: (body: string) => void;
  className?: string;
};

export function CommentComposer({ onSubmit, className }: CommentComposerProps) {
  const [body, setBody] = useState('');
  const me = currentUser();
  const trimmed = body.trim();
  const canSend = trimmed.length > 0;

  function submit() {
    if (!canSend) {
      return;
    }
    onSubmit(trimmed);
    setBody('');
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    submit();
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === 'Escape') {
      event.stopPropagation();
      event.currentTarget.blur();
      return;
    }
    const isCommand = event.metaKey || event.ctrlKey;
    if (event.key === 'Enter' && isCommand) {
      event.preventDefault();
      submit();
    }
  }

  return (
    <form
      onSubmit={handleSubmit}
      className={cn('flex items-start gap-2.5', className)}
    >
      <PersonAvatar person={me} className='mt-1 size-7 text-[10px]' />
      <div className='relative min-w-0 flex-1'>
        <Textarea
          value={body}
          onChange={(event) => setBody(event.target.value)}
          onKeyDown={handleKeyDown}
          rows={1}
          aria-label={`Comment as ${me.name}`}
          placeholder='Leave a comment'
          className='min-h-9 py-2 pe-24'
        />
        <Button
          type='submit'
          size='sm'
          disabled={!canSend}
          className='absolute end-1 bottom-1'
        >
          Comment
        </Button>
      </div>
    </form>
  );
}

import {
  BookmarkIcon,
  CheckIcon,
  CircleAlertIcon,
  ZapIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import type { IssueTypeId, Person, PriorityId, StatusId } from './data';
import { issueTypeOf, statusOf } from './detail-model';

const PIE_RADIUS = 2;
const PIE_CIRCUMFERENCE = 2 * Math.PI * PIE_RADIUS;

function pieDashOf(share: number) {
  const filled = share * PIE_CIRCUMFERENCE;
  return `${filled} ${PIE_CIRCUMFERENCE}`;
}

function StartedShape({ share }: { share: number }) {
  return (
    <>
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
      <circle
        cx='7'
        cy='7'
        r={PIE_RADIUS}
        stroke='currentColor'
        strokeWidth={PIE_RADIUS * 2}
        strokeDasharray={pieDashOf(share)}
        transform='rotate(-90 7 7)'
      />
    </>
  );
}

function statusShapeOf(status: StatusId) {
  if (status === 'backlog') {
    return (
      <circle
        cx='7'
        cy='7'
        r='6'
        stroke='currentColor'
        strokeWidth='1.5'
        strokeDasharray='1.6 1.9'
      />
    );
  }
  if (status === 'todo') {
    return (
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
    );
  }
  if (status === 'in_progress') {
    return <StartedShape share={0.5} />;
  }
  if (status === 'in_review') {
    return <StartedShape share={0.75} />;
  }
  return (
    <>
      <circle cx='7' cy='7' r='7' fill='currentColor' />
      <path
        d='M4.4 7.2 6.2 9l3.4-3.8'
        stroke='var(--card)'
        strokeWidth='1.6'
        strokeLinecap='round'
        strokeLinejoin='round'
      />
    </>
  );
}

export function StatusGlyph({
  status,
  className,
}: {
  status: StatusId;
  className?: string;
}) {
  const meta = statusOf(status);
  const glyphStyle = { color: meta.color } as React.CSSProperties;

  return (
    <svg
      viewBox='0 0 14 14'
      fill='none'
      aria-hidden='true'
      style={glyphStyle}
      className={cn('size-3.5 shrink-0', className)}
    >
      {statusShapeOf(status)}
    </svg>
  );
}

const PRIORITY_BARS = [
  { x: 1.5, height: 4 },
  { x: 5.75, height: 7 },
  { x: 10, height: 10 },
];

const FILLED_BAR_COUNT: Record<PriorityId, number> = {
  urgent: 3,
  high: 3,
  medium: 2,
  low: 1,
  none: 0,
};

function barOpacityOf(index: number, filledCount: number) {
  if (index < filledCount) {
    return 0.75;
  }
  return 0.2;
}

function priorityShapeOf(priority: PriorityId) {
  if (priority === 'urgent') {
    return (
      <g style={{ color: 'var(--destructive)' }}>
        <rect
          x='1'
          y='1'
          width='12'
          height='12'
          rx='3.5'
          fill='currentColor'
          fillOpacity='0.16'
        />
        <rect
          x='6.25'
          y='3.5'
          width='1.5'
          height='4.75'
          rx='0.75'
          fill='currentColor'
        />
        <circle cx='7' cy='10.1' r='0.95' fill='currentColor' />
      </g>
    );
  }
  if (priority === 'none') {
    return (
      <g fill='currentColor' fillOpacity='0.45'>
        {PRIORITY_BARS.map((bar) => (
          <rect
            key={bar.x}
            x={bar.x}
            y='6.25'
            width='2.5'
            height='1.5'
            rx='0.75'
          />
        ))}
      </g>
    );
  }
  const filledCount = FILLED_BAR_COUNT[priority];
  return (
    <g fill='currentColor'>
      {PRIORITY_BARS.map((bar, index) => (
        <rect
          key={bar.x}
          x={bar.x}
          y={12 - bar.height}
          width='2.5'
          height={bar.height}
          rx='0.75'
          fillOpacity={barOpacityOf(index, filledCount)}
        />
      ))}
    </g>
  );
}

export function PriorityGlyph({
  priority,
  className,
}: {
  priority: PriorityId;
  className?: string;
}) {
  return (
    <svg
      viewBox='0 0 14 14'
